    str.clear();
    str.append( "FUNCTION convert_spatial_to_ypr_rotation(\n" );
    str.append( "             pair : kinematic_pair;\n" );
    str.append( "             rotation : spatial_rotation\n" );
    str.append( "         ) : ypr_rotation;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    axis       : direction;\n" );
    str.append( "    angle      : plane_angle_measure;\n" );
    str.append( "    conv_angle : plane_angle_measure;\n" );
    str.append( "    ya         : plane_angle_measure;\n" );
    str.append( "    pa         : plane_angle_measure;\n" );
    str.append( "    ra         : plane_angle_measure;\n" );
    str.append( "    ucf        : REAL;\n" );
    str.append( "    dx         : REAL;\n" );
    str.append( "    dy         : REAL;\n" );
    str.append( "    dz         : REAL;\n" );
    str.append( "    s_a        : REAL;\n" );
    str.append( "    c_a        : REAL;\n" );
    str.append( "    rotmat     : ARRAY [1 : 3] OF ARRAY [1 : 3] OF REAL;\n" );
    str.append( "    cm1        : REAL;\n" );
    str.append( "    s_y        : REAL;\n" );
    str.append( "    c_y        : REAL;\n" );
    str.append( "    s_r        : REAL;\n" );
    str.append( "    c_r        : REAL;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.YPR_ROTATION' IN TYPEOF( rotation ) THEN\n" );
    str.append( "    RETURN( rotation );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  axis := normalise( rotation\\rotation_about_direction.direction_of_axis );\n" );
    str.append( "  angle := rotation\\rotation_about_direction.rotation_angle;\n" );
    str.append( "  IF angle = 0 THEN\n" );
    str.append( "    RETURN( [0, 0, 0] );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  dx := axis.direction_ratios[1];\n" );
    str.append( "  dy := axis.direction_ratios[2];\n" );
    str.append( "  dz := axis.direction_ratios[3];\n" );
    str.append( "  conv_angle := plane_angle_for_pair_in_radian( pair, angle );\n" );
    str.append( "  IF NOT ( 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.PLANE_ANGLE_MEASURE' IN TYPEOF( conv_angle ) ) THEN\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  ucf := angle / conv_angle;\n" );
    str.append( "  s_a := SIN( conv_angle );\n" );
    str.append( "  c_a := COS( conv_angle );\n" );
    str.append( "  IF ( dy = 0 ) AND ( ( dx * dz ) = 0 ) THEN\n" );
    str.append( "    REPEAT WHILE conv_angle <= ( -PI );\n" );
    str.append( "      conv_angle := conv_angle + ( 2 * PI );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    REPEAT WHILE conv_angle > PI;\n" );
    str.append( "      conv_angle := conv_angle - ( 2 * PI );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    ya := ucf * conv_angle;\n" );
    str.append( "    IF conv_angle <> PI THEN\n" );
    str.append( "      ra := -ya;\n" );
    str.append( "    ELSE\n" );
    str.append( "      ra := ya;\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF dx <> 0 THEN\n" );
    str.append( "      IF dx > 0 THEN\n" );
    str.append( "        RETURN( [0, 0, ya] );\n" );
    str.append( "      ELSE\n" );
    str.append( "        RETURN( [0, 0, ra] );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    ELSE\n" );
    str.append( "      IF dz > 0 THEN\n" );
    str.append( "        RETURN( [ya, 0, 0] );\n" );
    str.append( "      ELSE\n" );
    str.append( "        RETURN( [ra, 0, 0] );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( dy <> 0 ) AND ( dx = 0 ) AND ( dz = 0 ) THEN\n" );
    str.append( "    IF c_a >= 0 THEN\n" );
    str.append( "      ya := 0;\n" );
    str.append( "      ra := 0;\n" );
    str.append( "    ELSE\n" );
    str.append( "      ya := ucf * PI;\n" );
    str.append( "      ra := ya;\n" );
    str.append( "    END_IF;\n" );
    str.append( "    pa := ucf * ATAN( s_a, ABS( c_a ) );\n" );
    str.append( "    IF dy < 0 THEN\n" );
    str.append( "      pa := -pa;\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( [ya, pa, ra] );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  cm1 := 1 - c_a;\n" );
    str.append( "  rotmat := [[( dx * dx * cm1 ) + c_a, ( dx * dy * cm1 ) - ( dz * s_a ), ( dx * dz * cm1 ) + ( dy * s_a )], [( dx * dy * cm1 ) + \n" );
    str.append( "      ( dz * s_a ), ( dy * dy * cm1 ) + c_a, ( dy * dz * cm1 ) - ( dx * s_a )], [( dx * dz * cm1 ) - ( dy * s_a ), ( dy * dz * cm1 ) \n" );
    str.append( "      + ( dx * s_a ), ( dz * dz * cm1 ) + c_a]];\n" );
    str.append( "  IF ABS( rotmat[1][3] ) = 1 THEN\n" );
    str.append( "    BEGIN\n" );
    str.append( "      IF rotmat[1][3] = 1 THEN\n" );
    str.append( "        pa := 0.5 * PI;\n" );
    str.append( "      ELSE\n" );
    str.append( "        pa := ( -0.5 ) * PI;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      ra := 0;\n" );
    str.append( "      ya := ATAN( rotmat[2][1], rotmat[2][2] );\n" );
    str.append( "      IF rotmat[2][2] < 0 THEN\n" );
    str.append( "        IF ya <= 0 THEN\n" );
    str.append( "          ya := ya + PI;\n" );
    str.append( "        ELSE\n" );
    str.append( "          ya := ya - PI;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END;\n" );
    str.append( "  ELSE\n" );
    str.append( "    BEGIN\n" );
    str.append( "      ya := ATAN( -rotmat[1][2], rotmat[1][1] );\n" );
    str.append( "      IF rotmat[1][1] < 0 THEN\n" );
    str.append( "        IF ya <= 0 THEN\n" );
    str.append( "          ya := ya + PI;\n" );
    str.append( "        ELSE\n" );
    str.append( "          ya := ya - PI;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      ra := ATAN( -rotmat[2][3], rotmat[3][3] );\n" );
    str.append( "      IF rotmat[3][3] < 0 THEN\n" );
    str.append( "        IF ra <= 0 THEN\n" );
    str.append( "          ra := ra + PI;\n" );
    str.append( "        ELSE\n" );
    str.append( "          ra := ra - PI;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      s_y := SIN( ya );\n" );
    str.append( "      c_y := COS( ya );\n" );
    str.append( "      s_r := SIN( ra );\n" );
    str.append( "      c_r := COS( ra );\n" );
    str.append( "      IF ( ABS( s_y ) > ABS( c_y ) ) AND ( ABS( s_y ) > ABS( s_r ) ) AND ( ABS( s_y ) > ABS( c_r ) ) THEN\n" );
    str.append( "        cm1 := ( -rotmat[1][2] ) / s_y;\n" );
    str.append( "      ELSE\n" );
    str.append( "        IF ( ABS( c_y ) > ABS( s_r ) ) AND ( ABS( c_y ) > ABS( c_r ) ) THEN\n" );
    str.append( "          cm1 := rotmat[1][1] / c_y;\n" );
    str.append( "        ELSE\n" );
    str.append( "          IF ABS( s_r ) > ABS( c_r ) THEN\n" );
    str.append( "            cm1 := ( -rotmat[2][3] ) / s_r;\n" );
    str.append( "          ELSE\n" );
    str.append( "            cm1 := rotmat[3][3] / c_r;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      pa := ATAN( rotmat[1][3], cm1 );\n" );
    str.append( "    END;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  ya := ya * ucf;\n" );
    str.append( "  pa := pa * ucf;\n" );
    str.append( "  ra := ra * ucf;\n" );
    str.append( "  RETURN( [ya, pa, ra] );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
ap242_managed_model_based_3d_engineering_mim_lf::schema->AddFunction( str );
