    str.clear();
    str.append( "FUNCTION geometric_dimensionalities_in_contexts(\n" );
    str.append( "             grcs : SET [1 : ?] OF geometric_representation_context\n" );
    str.append( "         ) : INTEGER;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    grcs_1d : INTEGER := 0;\n" );
    str.append( "    grcs_2d : INTEGER := 0;\n" );
    str.append( "    grcs_3d : INTEGER := 0;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF SIZEOF( grcs ) = 1 THEN\n" );
    str.append( "    RETURN( grcs[1]\\geometric_representation_context.coordinate_space_dimension );\n" );
    str.append( "  ELSE\n" );
    str.append( "    REPEAT i := 1 TO HIINDEX( grcs ) BY 1;\n" );
    str.append( "      IF grcs[i]\\geometric_representation_context.coordinate_space_dimension = 1 THEN\n" );
    str.append( "        grcs_1d := grcs_1d + 1;\n" );
    str.append( "      ELSE\n" );
    str.append( "        IF grcs[i]\\geometric_representation_context.coordinate_space_dimension = 2 THEN\n" );
    str.append( "          grcs_2d := grcs_2d + 1;\n" );
    str.append( "        ELSE\n" );
    str.append( "          IF grcs[i]\\geometric_representation_context.coordinate_space_dimension = 3 THEN\n" );
    str.append( "            grcs_3d := grcs_3d + 1;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( grcs_1d + grcs_2d ) = 0 THEN\n" );
    str.append( "    RETURN( 3 );\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF ( grcs_1d + grcs_3d ) = 0 THEN\n" );
    str.append( "      RETURN( 2 );\n" );
    str.append( "    ELSE\n" );
    str.append( "      IF ( grcs_2d + grcs_3d ) = 0 THEN\n" );
    str.append( "        RETURN( 1 );\n" );
    str.append( "      ELSE\n" );
    str.append( "        RETURN( 0 );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "END_FUNCTION;\n" );
