    str.append( "  END_LOCAL;\n" );
    str.append( "  IF ( ( u1 - low1 ) + 1 ) <> SIZEOF( lis ) THEN\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( ( u2 - low2 ) + 1 ) <> SIZEOF( lis[1] ) THEN\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  res := [make_array_of_array( lis[1], low2, u2, low3, u3 ) : 0];\n" );
