    str.append( "    IF ( ( u2 - low2 ) + 1 ) <> SIZEOF( lis[i] ) THEN\n" );
    str.append( "      RETURN( ? );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    res[( low1 + i ) - 1] := make_array_of_array( lis[i], low2, u2, low3, u3 );\n" );
    str.append( "  END_REPEAT;\n" );
    str.append( "  RETURN( res );\n" );
