    str.clear();
    str.append( "FUNCTION substitute(\n" );
    str.append( "             expr : generic_expression;\n" );
    str.append( "             vars : LIST [1 : ?] OF generic_variable;\n" );
    str.append( "             vals : LIST [1 : ?] OF maths_value\n" );
    str.append( "         ) : generic_expression;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    types  : SET OF STRING := stripped_typeof( expr );\n" );
    str.append( "    opnds  : LIST OF generic_expression;\n" );
    str.append( "    op1    : generic_expression;\n" );
    str.append( "    op2    : generic_expression;\n" );
    str.append( "    qvars  : LIST OF generic_variable;\n" );
    str.append( "    srcdom : maths_space_or_function;\n" );
    str.append( "    prpfun : LIST [1 : ?] OF maths_function;\n" );
    str.append( "    finfun : maths_function_select;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF SIZEOF( vars ) <> SIZEOF( vals ) THEN\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'GENERIC_LITERAL' IN types THEN\n" );
    str.append( "    RETURN( expr );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'GENERIC_VARIABLE' IN types THEN\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( vars ) BY 1;\n" );
    str.append( "      IF expr :=: vars[i] THEN\n" );
    str.append( "        RETURN( vals[i] );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    RETURN( expr );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'QUANTIFIER_EXPRESSION' IN types THEN\n" );
    str.append( "    qvars := expr\\quantifier_expression.variables;\n" );
    str.append( "    REPEAT i := SIZEOF( vars ) TO 1 BY -1;\n" );
    str.append( "      IF vars[i] IN qvars THEN\n" );
    str.append( "        REMOVE( vars, i );\n" );
    str.append( "        REMOVE( vals, i );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    opnds := expr\\multiple_arity_generic_expression.operands;\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( opnds ) BY 1;\n" );
    str.append( "      IF NOT ( opnds[i] IN qvars ) THEN\n" );
    str.append( "        expr\\multiple_arity_generic_expression.operands[i] := substitute( opnds[i], vars, vals );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    RETURN( expr );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'UNARY_GENERIC_EXPRESSION' IN types THEN\n" );
    str.append( "    op1 := expr\\unary_generic_expression.operand;\n" );
    str.append( "    expr\\unary_generic_expression.operand := substitute( op1, vars, vals );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'BINARY_GENERIC_EXPRESSION' IN types THEN\n" );
    str.append( "    op1 := expr\\binary_generic_expression.operands[1];\n" );
    str.append( "    expr\\binary_generic_expression.operands[1] := substitute( op1, vars, vals );\n" );
    str.append( "    op2 := expr\\binary_generic_expression.operands[2];\n" );
    str.append( "    expr\\binary_generic_expression.operands[2] := substitute( op2, vars, vals );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'PARALLEL_COMPOSED_FUNCTION' IN types THEN\n" );
    str.append( "    srcdom := expr\\parallel_composed_function.source_of_domain;\n" );
    str.append( "    prpfun := expr\\parallel_composed_function.prep_functions;\n" );
    str.append( "    finfun := expr\\parallel_composed_function.final_function;\n" );
    str.append( "    srcdom := substitute( srcdom, vars, vals );\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( prpfun ) BY 1;\n" );
    str.append( "      prpfun[i] := substitute( prpfun[i], vars, vals );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    IF 'MATHS_FUNCTION' IN stripped_typeof( finfun ) THEN\n" );
    str.append( "      finfun := substitute( finfun, vars, vals );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( make_parallel_composed_function( srcdom, prpfun, finfun ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'MULTIPLE_ARITY_GENERIC_EXPRESSION' IN types THEN\n" );
    str.append( "    opnds := expr\\multiple_arity_generic_expression.operands;\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( opnds ) BY 1;\n" );
    str.append( "      expr\\multiple_arity_generic_expression.operands[i] := substitute( opnds[i], vars, vals );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( expr );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
ap242_managed_model_based_3d_engineering_mim_lf::schema->AddFunction( str );
    str.clear();
    str.append( "FUNCTION simplify_maths_space(\n" );
    str.append( "             spc : maths_space\n" );
    str.append( "         ) : maths_space;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    stypes   : SET OF STRING := stripped_typeof( spc );\n" );
    str.append( "    sset     : SET OF maths_value;\n" );
    str.append( "    zset     : SET OF maths_value := [];\n" );
    str.append( "    zval     : maths_value;\n" );
    str.append( "    zspc     : maths_space;\n" );
    str.append( "    zallint  : BOOLEAN := TRUE;\n" );
    str.append( "    zint     : INTEGER;\n" );
    str.append( "    zmin     : INTEGER;\n" );
    str.append( "    zmax     : INTEGER;\n" );
    str.append( "    factors  : LIST OF maths_space;\n" );
    str.append( "    zfactors : LIST OF maths_space := [];\n" );
    str.append( "    rspc     : maths_space;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF 'FINITE_SPACE' IN stypes THEN\n" );
    str.append( "    sset := spc\\finite_space.members;\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( sset ) BY 1;\n" );
    str.append( "      zval := simplify_maths_value( sset[i] );\n" );
    str.append( "      zset := zset + [zval];\n" );
    str.append( "      IF zallint AND ( 'INTEGER' IN TYPEOF( zval ) ) THEN\n" );
    str.append( "        zint := zval;\n" );
    str.append( "        IF i = 1 THEN\n" );
    str.append( "          zmin := zint;\n" );
    str.append( "          zmax := zint;\n" );
    str.append( "        ELSE\n" );
    str.append( "          IF zint < zmin THEN\n" );
    str.append( "            zmin := zint;\n" );
    str.append( "          END_IF;\n" );
    str.append( "          IF zint > zmax THEN\n" );
    str.append( "            zmax := zint;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      ELSE\n" );
    str.append( "        zallint := FALSE;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    IF zallint AND ( SIZEOF( zset ) = ( ( zmax - zmin ) + 1 ) ) THEN\n" );
    str.append( "      RETURN( make_finite_integer_interval( zmin, zmax ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( make_finite_space( zset ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'UNIFORM_PRODUCT_SPACE' IN stypes THEN\n" );
    str.append( "    zspc := simplify_maths_space( spc\\uniform_product_space.base );\n" );
    str.append( "    RETURN( make_uniform_product_space( zspc, spc\\uniform_product_space.exponent ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'LISTED_PRODUCT_SPACE' IN stypes THEN\n" );
    str.append( "    factors := spc\\listed_product_space.factors;\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( factors ) BY 1;\n" );
    str.append( "      INSERT( zfactors, simplify_maths_space( factors[i] ), i - 1 );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    RETURN( make_listed_product_space( zfactors ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'EXTENDED_TUPLE_SPACE' IN stypes THEN\n" );
