    str.append( "  FUNCTION angle(\n" );
    str.append( "               a : REAL\n" );
    str.append( "           ) : REAL;\n" );
    str.append( "    REPEAT WHILE a > PI;\n" );
    str.append( "      a := a - ( 2 * PI );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    REPEAT WHILE a <= ( -PI );\n" );
    str.append( "      a := a + ( 2 * PI );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    RETURN( a );\n" );
    str.append( "  END_FUNCTION;\n" );
    str.append( "  FUNCTION strictly_in(\n" );
    str.append( "               a : REAL;\n" );
    str.append( "               aitv : finite_real_interval\n" );
    str.append( "           ) : LOGICAL;\n" );
    str.append( "    a := angle( a );\n" );
    str.append( "    RETURN( ( ( aitv.min < a ) AND ( a < aitv.max ) ) OR ( ( aitv.min < ( a + ( 2 * PI ) ) ) AND ( ( a + ( 2 * PI ) ) < aitv.max ) ) );\n" );
    str.append( "  END_FUNCTION;\n" );
    str.append( "  PROCEDURE angle_range(\n" );
    str.append( "                VAR amin : REAL;\n" );
    str.append( "                VAR amax : REAL    );\n" );
    str.append( "    amin := angle( amin );\n" );
    str.append( "    IF amin = PI THEN\n" );
    str.append( "      amin := -PI;\n" );
    str.append( "    END_IF;\n" );
    str.append( "    amax := angle( amax );\n" );
    str.append( "    IF amax <= amin THEN\n" );
    str.append( "      amax := amax + ( 2 * PI );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_PROCEDURE;\n" );
