    str.append( "    minclo  : open_closed := open;\n" );
    str.append( "    maxclo  : open_closed := open;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF ( NOT EXISTS( prgn ) ) OR ( NOT EXISTS( centre ) ) THEN\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  xp := prgn.centre.real_part;\n" );
    str.append( "  yp := prgn.centre.imag_part;\n" );
    str.append( "  ritp := prgn.distance_constraint;\n" );
    str.append( "  aitp := prgn.direction_constraint;\n" );
    str.append( "  xc := centre.real_part;\n" );
    str.append( "  yc := centre.imag_part;\n" );
    str.append( "  IF ( xc = xp ) AND ( yc = yp ) THEN\n" );
    str.append( "    RETURN( prgn );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  rc := SQRT( ( ( xp - xc ) ** 2 ) + ( ( yp - yc ) ** 2 ) );\n" );
    str.append( "  acp := atan2( yp - yc, xp - xc );\n" );
    str.append( "  apc := atan2( yc - yp, xc - xp );\n" );
    str.append( "  rmnp := real_min( ritp );\n" );
    str.append( "  IF max_exists( ritp ) THEN\n" );
