    str.append( "    IF ( aitp.max - aitp.min ) = ( 2 * PI ) THEN\n" );
    str.append( "      inn := NOT max_included( aitp );\n" );
    str.append( "      a := angle( aitp.min );\n" );
    str.append( "      rmax := rc + rmxp;\n" );
