    str.append( "      IF inn AND ( acp = a ) THEN\n" );
    str.append( "        rmax_in := FALSE;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      IF rc > rmxp THEN\n" );
    str.append( "        a0 := ASIN( rmxp / rc );\n" );
