    str.append( "        IF amax < amin THEN\n" );
    str.append( "          amax := amax + ( 2 * PI );\n" );
    str.append( "        END_IF;\n" );
    str.append( "        rmin := rc - rmxp;\n" );
    str.append( "        rmin_in := amin_in;\n" );
