    str.append( "FUNCTION nondecreasing(\n" );
    str.append( "             lr : LIST OF REAL\n" );
    str.append( "         ) : BOOLEAN;\n" );
    str.append( "  IF NOT EXISTS( lr ) THEN\n" );
