    str.clear();
    str.append( "FUNCTION equal_maths_values(\n" );
    str.append( "             val1, val2 : maths_value\n" );
    str.append( "         ) : LOGICAL;\n" );
    str.append( "  FUNCTION mem_of_vs(\n" );
    str.append( "               val1, val2 : maths_value\n" );
    str.append( "           ) : LOGICAL;\n" );
    str.append( "    IF NOT has_values_space( val2 ) THEN\n" );
    str.append( "      RETURN( UNKNOWN );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF NOT member_of( val1, values_space_of( val2 ) ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( UNKNOWN );\n" );
    str.append( "  END_FUNCTION;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    types1 : SET OF STRING;\n" );
    str.append( "    types2 : SET OF STRING;\n" );
    str.append( "    list1  : LIST OF maths_value;\n" );
    str.append( "    list2  : LIST OF maths_value;\n" );
    str.append( "    cum    : LOGICAL := TRUE;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF ( NOT EXISTS( val1 ) ) OR ( NOT EXISTS( val2 ) ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF val1 = val2 THEN\n" );
