    str.append( "  types1 := stripped_typeof( val1 );\n" );
    str.append( "  types2 := stripped_typeof( val2 );\n" );
    str.append( "  IF ( 'MATHS_ATOM' IN types1 ) OR ( 'COMPLEX_NUMBER_LITERAL' IN types1 ) THEN\n" );
    str.append( "    IF 'MATHS_ATOM' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'COMPLEX_NUMBER_LITERAL' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'LIST' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'MATHS_SPACE' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
