    str.append( "    IF 'MATHS_FUNCTION' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'GENERIC_EXPRESSION' IN types2 THEN\n" );
    str.append( "      RETURN( mem_of_vs( val1, val2 ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( UNKNOWN );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( 'MATHS_ATOM' IN types2 ) OR ( 'COMPLEX_NUMBER_LITERAL' IN types2 ) THEN\n" );
    str.append( "    RETURN( equal_maths_values( val2, val1 ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'LIST' IN types1 THEN\n" );
    str.append( "    IF 'LIST' IN types2 THEN\n" );
    str.append( "      list1 := val1;\n" );
    str.append( "      list2 := val2;\n" );
    str.append( "      IF SIZEOF( list1 ) <> SIZEOF( list2 ) THEN\n" );
    str.append( "        RETURN( FALSE );\n" );
    str.append( "      END_IF;\n" );
    str.append( "      REPEAT i := 1 TO SIZEOF( list1 ) BY 1;\n" );
    str.append( "        cum := cum AND equal_maths_values( list1[i], list2[i] );\n" );
    str.append( "        IF cum = FALSE THEN\n" );
    str.append( "          RETURN( FALSE );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_REPEAT;\n" );
    str.append( "      RETURN( cum );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'MATHS_SPACE' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'MATHS_FUNCTION' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'GENERIC_EXPRESSION' IN types2 THEN\n" );
    str.append( "      RETURN( mem_of_vs( val1, val2 ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( UNKNOWN );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'LIST' IN types2 THEN\n" );
    str.append( "    RETURN( equal_maths_values( val2, val1 ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'MATHS_SPACE' IN types1 THEN\n" );
    str.append( "    IF 'MATHS_SPACE' IN types2 THEN\n" );
    str.append( "      RETURN( equal_maths_spaces( val1, val2 ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'MATHS_FUNCTION' IN types2 THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'GENERIC_EXPRESSION' IN types2 THEN\n" );
    str.append( "      RETURN( mem_of_vs( val1, val2 ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( UNKNOWN );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'MATHS_SPACE' IN types2 THEN\n" );
    str.append( "    RETURN( equal_maths_values( val2, val1 ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'MATHS_FUNCTION' IN types1 THEN\n" );
    str.append( "    IF 'MATHS_FUNCTION' IN types2 THEN\n" );
    str.append( "      RETURN( equal_maths_functions( val1, val2 ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'GENERIC_EXPRESSION' IN types2 THEN\n" );
    str.append( "      RETURN( mem_of_vs( val1, val2 ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( UNKNOWN );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'MATHS_FUNCTION' IN types2 THEN\n" );
    str.append( "    RETURN( equal_maths_values( val2, val1 ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( 'GENERIC_EXPRESSION' IN types1 ) AND ( 'GENERIC_EXPRESSION' IN types2 ) THEN\n" );
    str.append( "    IF ( NOT has_values_space( val1 ) ) OR ( NOT has_values_space( val2 ) ) THEN\n" );
    str.append( "      RETURN( UNKNOWN );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF NOT compatible_spaces( values_space_of( val1 ), values_space_of( val2 ) ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( UNKNOWN );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
