    str.clear();
    str.append( "FUNCTION parse_express_identifier(\n" );
    str.append( "             s : STRING;\n" );
    str.append( "             i : positive_integer\n" );
    str.append( "         ) : positive_integer;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    k : positive_integer;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  k := i;\n" );
    str.append( "  IF i <= LENGTH( s ) THEN\n" );
    str.append( "    IF s[i] LIKE '@' THEN\n" );
    str.append( "      REPEAT UNTIL ( k > LENGTH( s ) ) OR ( ( s[k] <> '_' ) AND ( NOT ( s[k] LIKE '@' ) ) AND ( NOT ( s[k] LIKE '#' ) ) );\n" );
