    str.clear();
    str.append( "FUNCTION enclose_pregion_in_cregion(\n" );
    str.append( "             prgn : polar_complex_number_region\n" );
    str.append( "         ) : cartesian_complex_number_region;\n" );
    str.append( "  PROCEDURE nearest_good_direction(\n" );
    str.append( "                acart : REAL;\n" );
    str.append( "                aitv : finite_real_interval;\n" );
    str.append( "                VAR a : REAL;\n" );
    str.append( "                VAR a_in : BOOLEAN    );\n" );
    str.append( "    a := acart;\n" );
    str.append( "    a_in := TRUE;\n" );
    str.append( "    IF a < aitv.min THEN\n" );
    str.append( "      IF ( a + ( 2 * PI ) ) < aitv.max THEN\n" );
    str.append( "        RETURN;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      IF ( a + ( 2 * PI ) ) = aitv.max THEN\n" );
    str.append( "        a_in := max_included( aitv );\n" );
    str.append( "        RETURN;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    ELSE\n" );
    str.append( "      IF a = aitv.min THEN\n" );
    str.append( "        a_in := min_included( aitv );\n" );
    str.append( "        RETURN;\n" );
    str.append( "      ELSE\n" );
    str.append( "        IF a < aitv.max THEN\n" );
    str.append( "          RETURN;\n" );
    str.append( "        ELSE\n" );
    str.append( "          IF a = aitv.max THEN\n" );
    str.append( "            a_in := max_included( aitv );\n" );
    str.append( "            RETURN;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF COS( acart - aitv.max ) >= COS( acart - aitv.min ) THEN\n" );
