    str.append( "      a_in := max_included( aitv );\n" );
    str.append( "    ELSE\n" );
    str.append( "      a := aitv.min;\n" );
    str.append( "      a_in := min_included( aitv );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_PROCEDURE;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    xc          : REAL := 0;\n" );
    str.append( "    yc          : REAL := 0;\n" );
    str.append( "    xmin        : REAL := 0;\n" );
    str.append( "    xmax        : REAL := 0;\n" );
    str.append( "    ymin        : REAL := 0;\n" );
    str.append( "    ymax        : REAL := 0;\n" );
    str.append( "    ritv        : real_interval;\n" );
    str.append( "    xitv        : real_interval;\n" );
    str.append( "    yitv        : real_interval;\n" );
    str.append( "    aitv        : finite_real_interval;\n" );
    str.append( "    xmin_exists : BOOLEAN;\n" );
    str.append( "    xmax_exists : BOOLEAN;\n" );
    str.append( "    ymin_exists : BOOLEAN;\n" );
    str.append( "    ymax_exists : BOOLEAN;\n" );
    str.append( "    xmin_in     : BOOLEAN := FALSE;\n" );
    str.append( "    xmax_in     : BOOLEAN := FALSE;\n" );
    str.append( "    ymin_in     : BOOLEAN := FALSE;\n" );
    str.append( "    ymax_in     : BOOLEAN := FALSE;\n" );
    str.append( "    a           : REAL := 0;\n" );
    str.append( "    r           : REAL := 0;\n" );
    str.append( "    a_in        : BOOLEAN := FALSE;\n" );
    str.append( "    min_clo     : open_closed := open;\n" );
