    str.append( "  yc := prgn.centre.imag_part;\n" );
    str.append( "  ritv := prgn.distance_constraint;\n" );
    str.append( "  aitv := prgn.direction_constraint;\n" );
    str.append( "  nearest_good_direction( PI, aitv, a, a_in );\n" );
    str.append( "  IF COS( a ) >= 0 THEN\n" );
    str.append( "    xmin_exists := TRUE;\n" );
