    str.append( "    xmin_in := a_in AND ( min_included( ritv ) OR ( COS( a ) = 0 ) );\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF max_exists( ritv ) THEN\n" );
    str.append( "      xmin_exists := TRUE;\n" );
    str.append( "      xmin := xc + ( real_max( ritv ) * COS( a ) );\n" );
    str.append( "      xmin_in := a_in AND max_included( ritv );\n" );
    str.append( "    ELSE\n" );
    str.append( "      xmin_exists := FALSE;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  nearest_good_direction( 0, aitv, a, a_in );\n" );
    str.append( "  IF COS( a ) <= 0 THEN\n" );
    str.append( "    xmax_exists := TRUE;\n" );
    str.append( "    xmax := xc + ( real_min( ritv ) * COS( a ) );\n" );
