    str.append( "    ELSE\n" );
    str.append( "      ymin_exists := FALSE;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  nearest_good_direction( 0.5 * PI, aitv, a, a_in );\n" );
    str.append( "  IF SIN( a ) <= 0 THEN\n" );
