    str.append( "    ymax_in := a_in AND ( min_included( ritv ) OR ( SIN( a ) = 0 ) );\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF max_exists( ritv ) THEN\n" );
    str.append( "      ymax_exists := TRUE;\n" );
    str.append( "      ymax := yc + ( real_max( ritv ) * SIN( a ) );\n" );
    str.append( "      ymax_in := a_in AND max_included( ritv );\n" );
    str.append( "    ELSE\n" );
    str.append( "      ymax_exists := FALSE;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF NOT ( xmin_exists OR xmax_exists OR ymin_exists OR ymax_exists ) THEN\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF xmin_exists THEN\n" );
    str.append( "    IF xmin_in THEN\n" );
    str.append( "      min_clo := closed;\n" );
    str.append( "    ELSE\n" );
    str.append( "      min_clo := open;\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF xmax_exists THEN\n" );
    str.append( "      IF xmax_in THEN\n" );
    str.append( "        max_clo := closed;\n" );
    str.append( "      ELSE\n" );
    str.append( "        max_clo := open;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      xitv := make_finite_real_interval( xmin, min_clo, xmax, max_clo );\n" );
    str.append( "    ELSE\n" );
    str.append( "      xitv := make_real_interval_from_min( xmin, min_clo );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF xmax_exists THEN\n" );
    str.append( "      IF xmax_in THEN\n" );
    str.append( "        max_clo := closed;\n" );
    str.append( "      ELSE\n" );
    str.append( "        max_clo := open;\n" );
