    str.append( "    ELSE\n" );
    str.append( "      min_clo := open;\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF ymax_exists THEN\n" );
    str.append( "      IF ymax_in THEN\n" );
    str.append( "        max_clo := closed;\n" );
    str.append( "      ELSE\n" );
    str.append( "        max_clo := open;\n" );
