    str.append( "  IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.UNARY_GENERIC_EXPRESSION' IN TYPEOF( arg1 ) THEN\n" );
    str.append( "    RETURN( acyclic( arg1\\unary_generic_expression.operand, arg2 + [arg1] ) );\n" );
