    str.append( "FUNCTION shape_of_array(\n" );
    str.append( "             func : maths_function\n" );
    str.append( "         ) : LIST OF positive_integer;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    tspace : tuple_space;\n" );
    str.append( "    temp   : maths_space;\n" );
    str.append( "    result : LIST OF positive_integer := [];\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF ( schema_prefix + 'EXPLICIT_TABLE_FUNCTION' ) IN TYPEOF( func ) THEN\n" );
    str.append( "    RETURN( func\\explicit_table_function.shape );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  tspace := func.domain;\n" );
    str.append( "  IF ( space_dimension( tspace ) = 1 ) AND ( ( schema_prefix + 'TUPLE_SPACE' ) IN TYPEOF( factor1( tspace ) ) ) THEN\n" );
    str.append( "    tspace := factor1( tspace );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  REPEAT i := 1 TO space_dimension( tspace ) BY 1;\n" );
    str.append( "    temp := factor_space( tspace, i );\n" );
    str.append( "    IF NOT ( ( schema_prefix + 'FINITE_INTEGER_INTERVAL' ) IN TYPEOF( temp ) ) THEN\n" );
    str.append( "      RETURN( ? );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    INSERT( result, temp\\finite_integer_interval.size, i - 1 );\n" );
    str.append( "  END_REPEAT;\n" );
    str.append( "  RETURN( result );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
ap242_managed_model_based_3d_engineering_mim_lf::schema->AddFunction( str );
