    str.clear();
    str.append( "FUNCTION derive_function_domain(\n" );
    str.append( "             func : maths_function\n" );
    str.append( "         ) : tuple_space;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    typenames  : SET OF STRING := stripped_typeof( func );\n" );
    str.append( "    tspace     : tuple_space := make_listed_product_space( [] );\n" );
    str.append( "    shape      : LIST OF positive_integer;\n" );
    str.append( "    sidxs      : LIST OF INTEGER := [0];\n" );
    str.append( "    itvl       : finite_integer_interval;\n" );
    str.append( "    factors    : LIST OF finite_integer_interval := [];\n" );
    str.append( "    is_uniform : BOOLEAN := TRUE;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF 'FINITE_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( derive_finite_function_domain( func\\finite_function.pairs ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'CONSTANT_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( domain_from( func\\constant_function.source_of_domain ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'SELECTOR_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( domain_from( func\\selector_function.source_of_domain ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'ELEMENTARY_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( derive_elementary_function_domain( func\\elementary_function.func_id ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'RESTRICTION_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( one_tuples_of( func\\restriction_function.operand ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'REPACKAGING_FUNCTION' IN typenames THEN\n" );
    str.append( "    IF func\\repackaging_function.input_repack = ro_nochange THEN\n" );
    str.append( "      RETURN( func\\repackaging_function.operand.domain );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF func\\repackaging_function.input_repack = ro_wrap_as_tuple THEN\n" );
    str.append( "      RETURN( factor1( func\\repackaging_function.operand.domain ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF func\\repackaging_function.input_repack = ro_unwrap_tuple THEN\n" );
    str.append( "      RETURN( one_tuples_of( func\\repackaging_function.operand.domain ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'REINDEXED_ARRAY_FUNCTION' IN typenames THEN\n" );
    str.append( "    shape := shape_of_array( func\\unary_generic_expression.operand );\n" );
    str.append( "    sidxs := func\\reindexed_array_function.starting_indices;\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( shape ) BY 1;\n" );
    str.append( "      itvl := make_finite_integer_interval( sidxs[i], ( sidxs[i] + shape[i] ) - 1 );\n" );
    str.append( "      INSERT( factors, itvl, i - 1 );\n" );
    str.append( "      IF shape[i] <> shape[1] THEN\n" );
    str.append( "        is_uniform := FALSE;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    IF is_uniform THEN\n" );
    str.append( "      RETURN( make_uniform_product_space( factors[1], SIZEOF( shape ) ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( make_listed_product_space( factors ) );\n" );
