    str.append( "  IF 'SERIES_COMPOSED_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( func\\series_composed_function.operands[1].domain );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'PARALLEL_COMPOSED_FUNCTION' IN typenames THEN\n" );
