    str.append( "        homogeneous_linear_function.mat\\explicit_table_function.shape[func\\homogeneous_linear_function.sum_index] ) ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'GENERAL_LINEAR_FUNCTION' IN typenames THEN\n" );
