    str.append( "  IF 'PARTIAL_DERIVATIVE_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( func\\partial_derivative_function.derivand.domain );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'DEFINITE_INTEGRAL_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( derive_definite_integral_domain( func ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'ABSTRACTED_EXPRESSION_FUNCTION' IN typenames THEN\n" );
    str.append( "    REPEAT i := 1 TO SIZEOF( func\\abstracted_expression_function.variables ) BY 1;\n" );
    str.append( "      tspace := assoc_product_space( tspace, one_tuples_of( values_space_of( func\\abstracted_expression_function.variables[i] ) ) );\n" );
