    str.append( "    RETURN( tspace );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'EXPRESSION_DENOTED_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( values_space_of( func\\expression_denoted_function.expr )\\function_space.domain_argument );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'IMPORTED_POINT_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( one_tuples_of( make_listed_product_space( [] ) ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'IMPORTED_CURVE_FUNCTION' IN typenames THEN\n" );
    str.append( "    RETURN( func\\imported_curve_function.parametric_domain );\n" );
    str.append( "  END_IF;\n" );
