    str.append( "  LOCAL\n" );
    str.append( "    tspace : tuple_space;\n" );
    str.append( "    temp   : maths_space;\n" );
    str.append( "    base   : INTEGER;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF NOT EXISTS( func ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  tspace := func.domain;\n" );
    str.append( "  IF ( space_dimension( tspace ) = 1 ) AND ( ( schema_prefix + 'TUPLE_SPACE' ) IN TYPEOF( factor1( tspace ) ) ) THEN\n" );
    str.append( "    tspace := factor1( tspace );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF NOT ( ( schema_prefix + 'PRODUCT_SPACE' ) IN TYPEOF( tspace ) ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  temp := factor1( tspace );\n" );
    str.append( "  IF NOT ( ( schema_prefix + 'FINITE_INTEGER_INTERVAL' ) IN TYPEOF( temp ) ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  base := temp\\finite_integer_interval.min;\n" );
    str.append( "  IF ( base <> 0 ) AND ( base <> 1 ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  REPEAT i := 2 TO space_dimension( tspace ) BY 1;\n" );
    str.append( "    temp := factor_space( tspace, i );\n" );
    str.append( "    IF NOT ( ( schema_prefix + 'FINITE_INTEGER_INTERVAL' ) IN TYPEOF( temp ) ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF temp\\finite_integer_interval.min <> base THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_REPEAT;\n" );
    str.append( "  RETURN( TRUE );\n" );
