    str.append( "FUNCTION using_representation_with_mapping(\n" );
    str.append( "             item : representation_item\n" );
    str.append( "         ) : SET OF representation;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    results                  : SET OF representation := [];\n" );
    str.append( "    local_results            : SET OF representation := [];\n" );
    str.append( "    local_representation_map : SET OF representation_map := [];\n" );
    str.append( "    intermediate_items       : SET OF representation_item := [];\n" );
    str.append( "    i                        : INTEGER;\n" );
    str.append( "    j                        : INTEGER;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  local_results := QUERY ( z <* using_representations( item ) | ( SIZEOF( USEDIN( z, \n" );
    str.append( "      'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.REPRESENTATION_MAP.MAPPED_REPRESENTATION'  ) ) > 0 ) );\n" );
    str.append( "  IF SIZEOF( local_results ) = 0 THEN\n" );
    str.append( "    RETURN( [] );\n" );
    str.append( "  ELSE\n" );
    str.append( "    REPEAT i := 1 TO HIINDEX( local_results ) BY 1;\n" );
    str.append( "      local_representation_map := local_representation_map + bag_to_set( USEDIN( local_results[i], \n" );
    str.append( "          'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.REPRESENTATION_MAP.MAPPED_REPRESENTATION'  ) );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    REPEAT i := 1 TO HIINDEX( local_representation_map ) BY 1;\n" );
    str.append( "      intermediate_items := intermediate_items + bag_to_set( USEDIN( local_representation_map[i], \n" );
    str.append( "          'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.MAPPED_ITEM.MAPPING_SOURCE'  ) );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    REPEAT j := 1 TO HIINDEX( intermediate_items ) BY 1;\n" );
    str.append( "      results := results + bag_to_set( using_representation_with_mapping( intermediate_items[j] ) );\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( results );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
