    str.append( "FUNCTION dot_count(\n" );
    str.append( "             str : STRING\n" );
    str.append( "         ) : INTEGER;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    n : INTEGER := 0;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  REPEAT i := 1 TO LENGTH( str ) BY 1;\n" );
    str.append( "    IF str[i] = '.' THEN\n" );
    str.append( "      n := n + 1;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_REPEAT;\n" );
    str.append( "  RETURN( n );\n" );
