    str.append( "FUNCTION list_to_set(\n" );
    str.append( "             l : LIST [0 : ?] OF GENERIC:t\n" );
    str.append( "         ) : SET OF GENERIC:t;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    s : SET OF GENERIC:t := [];\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  REPEAT i := 1 TO SIZEOF( l ) BY 1;\n" );
