    str.append( "FUNCTION min_included(\n" );
    str.append( "             spc : maths_space\n" );
    str.append( "         ) : BOOLEAN;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    types : SET OF STRING := TYPEOF( spc );\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF ( ( schema_prefix + 'FINITE_INTEGER_INTERVAL' ) IN types ) OR ( ( schema_prefix + 'INTEGER_INTERVAL_FROM_MIN' ) IN types )\n" );
    str.append( "      THEN\n" );
    str.append( "    RETURN( TRUE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( schema_prefix + 'FINITE_REAL_INTERVAL' ) IN types THEN\n" );
    str.append( "    RETURN( bool( spc\\finite_real_interval.min_closure = closed ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( schema_prefix + 'REAL_INTERVAL_FROM_MIN' ) IN types THEN\n" );
    str.append( "    RETURN( bool( spc\\real_interval_from_min.min_closure = closed ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( FALSE );\n" );
    str.append( "END_FUNCTION;\n" );
