    str.append( "    local_relation  : SET OF assembly_component_usage := [];\n" );
    str.append( "    local_relation2 : BAG OF assembly_component_usage := [];\n" );
    str.append( "    local_parent    : SET OF product_definition := [];\n" );
    str.append( "    root            : SET OF product_definition;\n" );
    str.append( "    i               : INTEGER := 0;\n" );
    str.append( "    j               : INTEGER := 0;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF ( SIZEOF( constituent ) = 1 ) AND assembly_root( constituent[1] ) THEN\n" );
    str.append( "    RETURN( [constituent[1]] );\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF SIZEOF( constituent ) = 0 THEN\n" );
    str.append( "      RETURN( [] );\n" );
    str.append( "    ELSE\n" );
    str.append( "      REPEAT j := 1 TO HIINDEX( constituent ) BY 1;\n" );
    str.append( "        local_relation2 := local_relation2 + QUERY ( pdr <* USEDIN( constituent[j], \n" );
    str.append( "            'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.PRODUCT_DEFINITION_RELATIONSHIP.RELATED_PRODUCT_DEFINITION'  ) | ( \n" );
    str.append( "            'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.ASSEMBLY_COMPONENT_USAGE'  IN TYPEOF( pdr ) ) );\n" );
    str.append( "      END_REPEAT;\n" );
    str.append( "      local_relation := bag_to_set( local_relation2 );\n" );
    str.append( "      IF SIZEOF( local_relation ) = 0 THEN\n" );
    str.append( "        IF SIZEOF( constituent ) = 1 THEN\n" );
    str.append( "          RETURN( [constituent[1]] );\n" );
    str.append( "        ELSE\n" );
    str.append( "          RETURN( [] );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      ELSE\n" );
    str.append( "        REPEAT i := 1 TO HIINDEX( local_relation ) BY 1;\n" );
    str.append( "          REPEAT j := 1 TO HIINDEX( constituent ) BY 1;\n" );
    str.append( "            IF local_relation[i].relating_product_definition <> constituent[j] THEN\n" );
    str.append( "              local_parent := local_parent + local_relation[i].relating_product_definition;\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_REPEAT;\n" );
    str.append( "        END_REPEAT;\n" );
    str.append( "        IF ( SIZEOF( local_parent ) = 1 ) AND assembly_root( local_parent[1] ) THEN\n" );
    str.append( "          RETURN( [local_parent[1]] );\n" );
    str.append( "        ELSE\n" );
    str.append( "          IF SIZEOF( local_parent ) = 0 THEN\n" );
    str.append( "            RETURN( [] );\n" );
    str.append( "          ELSE\n" );
    str.append( "            root := find_assembly_root( local_parent );\n" );
    str.append( "            IF SIZEOF( root ) = 1 THEN\n" );
    str.append( "              RETURN( root );\n" );
    str.append( "            ELSE\n" );
    str.append( "              IF SIZEOF( root ) = 0 THEN\n" );
    str.append( "                RETURN( [] );\n" );
    str.append( "              END_IF;\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( [] );\n" );
