    str.clear();
    str.append( "FUNCTION member_of(\n" );
    str.append( "             val : GENERIC:g;\n" );
    str.append( "             spc : maths_space\n" );
    str.append( "         ) : LOGICAL;\n" );
    str.append( "  FUNCTION fedex(\n" );
    str.append( "               val : AGGREGATE OF GENERIC:x;\n" );
    str.append( "               i : INTEGER\n" );
    str.append( "           ) : GENERIC:x;\n" );
    str.append( "    RETURN( val[i] );\n" );
    str.append( "  END_FUNCTION;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    v         : maths_value := simplify_maths_value( convert_to_maths_value( val ) );\n" );
    str.append( "    vtypes    : SET OF STRING := stripped_typeof( v );\n" );
    str.append( "    s         : maths_space := simplify_maths_space( spc );\n" );
    str.append( "    stypes    : SET OF STRING := stripped_typeof( s );\n" );
    str.append( "    tmp_int   : INTEGER;\n" );
    str.append( "    tmp_real  : REAL;\n" );
    str.append( "    tmp_cmplx : complex_number_literal;\n" );
