    str.append( "  END_IF;\n" );
    str.append( "  IF ( 'GENERIC_EXPRESSION' IN vtypes ) AND ( NOT ( 'MATHS_SPACE' IN vtypes ) ) AND ( NOT ( 'MATHS_FUNCTION' IN vtypes ) ) AND ( \n" );
    str.append( "      NOT ( 'COMPLEX_NUMBER_LITERAL' IN vtypes ) ) THEN\n" );
    str.append( "    IF has_values_space( v ) THEN\n" );
    str.append( "      vspc := values_space_of( v );\n" );
    str.append( "      IF subspace_of( vspc, s ) THEN\n" );
