    str.append( "      END_IF;\n" );
    str.append( "      IF NOT compatible_spaces( vspc, s ) THEN\n" );
    str.append( "        RETURN( FALSE );\n" );
    str.append( "      END_IF;\n" );
    str.append( "      RETURN( UNKNOWN );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( UNKNOWN );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'ELEMENTARY_SPACE' IN stypes THEN\n" );
    str.append( "    CASE s\\elementary_space.space_id OF\n" );
    str.append( "      es_numbers        :         RETURN( ( 'NUMBER' IN vtypes ) OR ( 'COMPLEX_NUMBER_LITERAL' IN vtypes ) );\n" );
    str.append( "      es_complex_numbers :         RETURN( 'COMPLEX_NUMBER_LITERAL' IN vtypes );\n" );
    str.append( "      es_reals          :         RETURN( ( 'REAL' IN vtypes ) AND ( NOT ( 'INTEGER' IN vtypes ) ) );\n" );
    str.append( "      es_integers       :         RETURN( 'INTEGER' IN vtypes );\n" );
    str.append( "      es_logicals       :         RETURN( 'LOGICAL' IN vtypes );\n" );
    str.append( "      es_booleans       :         RETURN( 'BOOLEAN' IN vtypes );\n" );
    str.append( "      es_strings        :         RETURN( 'STRING' IN vtypes );\n" );
    str.append( "      es_binarys        :         RETURN( 'BINARY' IN vtypes );\n" );
    str.append( "      es_maths_spaces   :         RETURN( 'MATHS_SPACE' IN vtypes );\n" );
    str.append( "      es_maths_functions :         RETURN( 'MATHS_FUNCTION' IN vtypes );\n" );
    str.append( "      es_generics       :         RETURN( TRUE );\n" );
