    str.append( "  END_IF;\n" );
    str.append( "  IF 'FINITE_INTEGER_INTERVAL' IN stypes THEN\n" );
    str.append( "    IF 'INTEGER' IN vtypes THEN\n" );
    str.append( "      tmp_int := v;\n" );
    str.append( "      RETURN( ( s\\finite_integer_interval.min <= tmp_int ) AND ( tmp_int <= s\\finite_integer_interval.max ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'INTEGER_INTERVAL_FROM_MIN' IN stypes THEN\n" );
    str.append( "    IF 'INTEGER' IN vtypes THEN\n" );
    str.append( "      tmp_int := v;\n" );
    str.append( "      RETURN( s\\integer_interval_from_min.min <= tmp_int );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( FALSE );\n" );
