    str.append( "  IF 'INTEGER_INTERVAL_TO_MAX' IN stypes THEN\n" );
    str.append( "    IF 'INTEGER' IN vtypes THEN\n" );
    str.append( "      tmp_int := v;\n" );
    str.append( "      RETURN( tmp_int <= s\\integer_interval_to_max.max );\n" );
