    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'FINITE_REAL_INTERVAL' IN stypes THEN\n" );
    str.append( "    IF ( 'REAL' IN vtypes ) AND ( NOT ( 'INTEGER' IN vtypes ) ) THEN\n" );
    str.append( "      tmp_real := v;\n" );
    str.append( "      IF s\\finite_real_interval.min_closure = closed THEN\n" );
    str.append( "        IF s\\finite_real_interval.max_closure = closed THEN\n" );
    str.append( "          RETURN( ( s\\finite_real_interval.min <= tmp_real ) AND ( tmp_real <= s\\finite_real_interval.max ) );\n" );
    str.append( "        ELSE\n" );
