    str.append( "FUNCTION compatible_complex_number_regions(\n" );
    str.append( "             sp1, sp2 : maths_space\n" );
    str.append( "         ) : BOOLEAN;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    typenames   : SET OF STRING := stripped_typeof( sp1 );\n" );
    str.append( "    crgn1       : cartesian_complex_number_region;\n" );
    str.append( "    crgn2       : cartesian_complex_number_region;\n" );
    str.append( "    prgn1       : polar_complex_number_region;\n" );
    str.append( "    prgn2       : polar_complex_number_region;\n" );
    str.append( "    prgn1c2     : polar_complex_number_region;\n" );
    str.append( "    prgn2c1     : polar_complex_number_region;\n" );
    str.append( "    sp1_is_crgn : BOOLEAN;\n" );
    str.append( "    sp2_is_crgn : BOOLEAN;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF 'CARTESIAN_COMPLEX_NUMBER_REGION' IN typenames THEN\n" );
    str.append( "    sp1_is_crgn := TRUE;\n" );
    str.append( "    crgn1 := sp1;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF 'POLAR_COMPLEX_NUMBER_REGION' IN typenames THEN\n" );
    str.append( "      sp1_is_crgn := FALSE;\n" );
    str.append( "      prgn1 := sp1;\n" );
    str.append( "    ELSE\n" );
    str.append( "      RETURN( TRUE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  typenames := stripped_typeof( sp2 );\n" );
    str.append( "  IF 'CARTESIAN_COMPLEX_NUMBER_REGION' IN typenames THEN\n" );
    str.append( "    sp2_is_crgn := TRUE;\n" );
    str.append( "    crgn2 := sp2;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF 'POLAR_COMPLEX_NUMBER_REGION' IN typenames THEN\n" );
    str.append( "      sp2_is_crgn := FALSE;\n" );
    str.append( "      prgn2 := sp2;\n" );
    str.append( "    ELSE\n" );
    str.append( "      RETURN( TRUE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF sp1_is_crgn AND sp2_is_crgn THEN\n" );
    str.append( "    RETURN( compatible_intervals( crgn1.real_constraint, crgn2.real_constraint ) AND compatible_intervals( crgn1.imag_constraint, \n" );
    str.append( "        crgn2.imag_constraint ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( NOT sp1_is_crgn ) AND ( NOT sp2_is_crgn ) AND ( prgn1.centre.real_part = prgn2.centre.real_part ) AND ( prgn1.centre.\n" );
    str.append( "      imag_part = prgn2.centre.imag_part ) THEN\n" );
    str.append( "    IF NOT compatible_intervals( prgn1.distance_constraint, prgn2.distance_constraint ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF compatible_intervals( prgn1.direction_constraint, prgn2.direction_constraint ) THEN\n" );
    str.append( "      RETURN( TRUE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF ( prgn1.direction_constraint.max > PI ) AND ( prgn2.direction_constraint.max < PI ) THEN\n" );
    str.append( "      RETURN( compatible_intervals( prgn2.direction_constraint, make_finite_real_interval( -PI, open, prgn1.direction_constraint.\n" );
    str.append( "          max - ( 2 * PI ), prgn1.direction_constraint.max_closure ) ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF ( prgn2.direction_constraint.max > PI ) AND ( prgn1.direction_constraint.max < PI ) THEN\n" );
    str.append( "      RETURN( compatible_intervals( prgn1.direction_constraint, make_finite_real_interval( -PI, open, prgn2.direction_constraint.\n" );
    str.append( "          max - ( 2 * PI ), prgn2.direction_constraint.max_closure ) ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF sp1_is_crgn AND ( NOT sp2_is_crgn ) THEN\n" );
    str.append( "    crgn2 := enclose_pregion_in_cregion( prgn2 );\n" );
    str.append( "    prgn1 := enclose_cregion_in_pregion( crgn1, prgn2.centre );\n" );
    str.append( "    RETURN( compatible_complex_number_regions( crgn1, crgn2 ) AND compatible_complex_number_regions( prgn1, prgn2 ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( NOT sp1_is_crgn ) AND sp2_is_crgn THEN\n" );
    str.append( "    crgn1 := enclose_pregion_in_cregion( prgn1 );\n" );
    str.append( "    prgn2 := enclose_cregion_in_pregion( crgn2, prgn1.centre );\n" );
    str.append( "    RETURN( compatible_complex_number_regions( crgn1, crgn2 ) AND compatible_complex_number_regions( prgn1, prgn2 ) );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  prgn1c2 := enclose_pregion_in_pregion( prgn1, prgn2.centre );\n" );
    str.append( "  prgn2c1 := enclose_pregion_in_pregion( prgn2, prgn1.centre );\n" );
    str.append( "  RETURN( compatible_complex_number_regions( prgn1, prgn2c1 ) AND compatible_complex_number_regions( prgn1c2, prgn2 ) );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
ap242_managed_model_based_3d_engineering_mim_lf::schema->AddFunction( str );
