    str.append( "FUNCTION equal_maths_functions(\n" );
    str.append( "             fun1, fun2 : maths_function\n" );
    str.append( "         ) : LOGICAL;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    cum : LOGICAL;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF fun1 = fun2 THEN\n" );
    str.append( "    RETURN( TRUE );\n" );
