    str.append( "  cum := equal_maths_spaces( fun1.domain, fun2.domain );\n" );
    str.append( "  IF cum = FALSE THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  cum := cum AND equal_maths_spaces( fun1.range, fun2.range );\n" );
    str.append( "  IF cum = FALSE THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( UNKNOWN );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
