    str.append( "FUNCTION assoc_product_space(\n" );
    str.append( "             ts1, ts2 : tuple_space\n" );
    str.append( "         ) : tuple_space;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    types1  : SET OF STRING := stripped_typeof( ts1 );\n" );
    str.append( "    types2  : SET OF STRING := stripped_typeof( ts2 );\n" );
    str.append( "    up1     : uniform_product_space := make_uniform_product_space( the_reals, 1 );\n" );
    str.append( "    up2     : uniform_product_space := make_uniform_product_space( the_reals, 1 );\n" );
    str.append( "    lp1     : listed_product_space := the_zero_tuple_space;\n" );
    str.append( "    lp2     : listed_product_space := the_zero_tuple_space;\n" );
    str.append( "    lps     : listed_product_space := the_zero_tuple_space;\n" );
    str.append( "    et1     : extended_tuple_space := the_tuples;\n" );
    str.append( "    et2     : extended_tuple_space := the_tuples;\n" );
    str.append( "    ets     : extended_tuple_space := the_tuples;\n" );
    str.append( "    use_up1 : BOOLEAN;\n" );
    str.append( "    use_up2 : BOOLEAN;\n" );
    str.append( "    use_lp1 : BOOLEAN;\n" );
    str.append( "    use_lp2 : BOOLEAN;\n" );
    str.append( "    factors : LIST OF maths_space := [];\n" );
    str.append( "    tspace  : tuple_space;\n" );
