    str.append( "  IF 'UNIFORM_PRODUCT_SPACE' IN types1 THEN\n" );
    str.append( "    up1 := ts1;\n" );
    str.append( "    use_up1 := TRUE;\n" );
    str.append( "    use_lp1 := FALSE;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF 'LISTED_PRODUCT_SPACE' IN types1 THEN\n" );
    str.append( "      lp1 := ts1;\n" );
    str.append( "      use_up1 := FALSE;\n" );
    str.append( "      use_lp1 := TRUE;\n" );
