    str.append( "      et1 := ts1;\n" );
    str.append( "      use_up1 := FALSE;\n" );
    str.append( "      use_lp1 := FALSE;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'UNIFORM_PRODUCT_SPACE' IN types2 THEN\n" );
    str.append( "    up2 := ts2;\n" );
    str.append( "    use_up2 := TRUE;\n" );
    str.append( "    use_lp2 := FALSE;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF 'LISTED_PRODUCT_SPACE' IN types2 THEN\n" );
    str.append( "      lp2 := ts2;\n" );
    str.append( "      use_up2 := FALSE;\n" );
    str.append( "      use_lp2 := TRUE;\n" );
    str.append( "    ELSE\n" );
    str.append( "      IF NOT ( 'EXTENDED_TUPLE_SPACE' IN types2 ) THEN\n" );
    str.append( "        RETURN( ? );\n" );
    str.append( "      END_IF;\n" );
    str.append( "      et2 := ts2;\n" );
    str.append( "      use_up2 := FALSE;\n" );
    str.append( "      use_lp2 := FALSE;\n" );
    str.append( "    END_IF;\n" );
