    str.append( "  IF use_up1 THEN\n" );
    str.append( "    IF use_up2 THEN\n" );
    str.append( "      IF up1.base = up2.base THEN\n" );
    str.append( "        tspace := make_uniform_product_space( up1.base, up1.exponent + up2.exponent );\n" );
    str.append( "      ELSE\n" );
    str.append( "        factors := [up1.base : 0, up2.base : 0];\n" );
    str.append( "        tspace := make_listed_product_space( factors );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    ELSE\n" );
    str.append( "      IF use_lp2 THEN\n" );
    str.append( "        factors := [up1.base : 0];\n" );
    str.append( "        factors := factors + lp2.factors;\n" );
    str.append( "        tspace := make_listed_product_space( factors );\n" );
    str.append( "      ELSE\n" );
    str.append( "        tspace := assoc_product_space( up1, et2.base );\n" );
    str.append( "        tspace := make_extended_tuple_space( tspace, et2.extender );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF use_lp1 THEN\n" );
    str.append( "      IF use_up2 THEN\n" );
    str.append( "        factors := [up2.base : 0];\n" );
    str.append( "        factors := lp1.factors + factors;\n" );
    str.append( "        tspace := make_listed_product_space( factors );\n" );
    str.append( "      ELSE\n" );
    str.append( "        IF use_lp2 THEN\n" );
    str.append( "          tspace := make_listed_product_space( lp1.factors + lp2.factors );\n" );
    str.append( "        ELSE\n" );
    str.append( "          tspace := assoc_product_space( lp1, et2.base );\n" );
    str.append( "          tspace := make_extended_tuple_space( tspace, et2.extender );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    ELSE\n" );
    str.append( "      IF use_up2 THEN\n" );
    str.append( "        IF et1.extender = up2.base THEN\n" );
    str.append( "          tspace := assoc_product_space( et1.base, up2 );\n" );
    str.append( "          tspace := make_extended_tuple_space( tspace, et1.extender );\n" );
    str.append( "        ELSE\n" );
    str.append( "          RETURN( ? );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      ELSE\n" );
    str.append( "        IF use_lp2 THEN\n" );
    str.append( "          factors := lp2.factors;\n" );
