    str.append( "            IF et1.extender <> factors[i] THEN\n" );
    str.append( "              RETURN( ? );\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_REPEAT;\n" );
    str.append( "          tspace := assoc_product_space( et1.base, lp2 );\n" );
    str.append( "          tspace := make_extended_tuple_space( tspace, et1.extender );\n" );
    str.append( "        ELSE\n" );
    str.append( "          IF et1.extender = et2.extender THEN\n" );
    str.append( "            tspace := assoc_product_space( et1, et2.base );\n" );
    str.append( "          ELSE\n" );
    str.append( "            RETURN( ? );\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( tspace );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
