    str.clear();
    str.append( "FUNCTION a3ms_validate_detected_difference_types(\n" );
    str.append( "             ei : data_equivalence_inspection_report;\n" );
    str.append( "             cr : a3m_equivalence_criterion_for_shape\n" );
    str.append( "         ) : LOGICAL;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    deiir   : data_equivalence_inspection_instance_report;\n" );
    str.append( "    eiriwei : equivalence_instance_report_item_with_notable_instances;\n" );
    str.append( "    addtn   : a3ms_detected_difference_type_name;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.DATA_EQUIVALENCE_INSPECTION_INSTANCE_REPORT' IN TYPEOF( ei ) THEN\n" );
    str.append( "    deiir := ei;\n" );
