    str.append( "      IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.EQUIVALENCE_INSTANCE_REPORT_ITEM_WITH_NOTABLE_INSTANCES' IN TYPEOF( \n" );
    str.append( "          deiir.inspected_instances[i] ) THEN\n" );
