    str.append( "              END_IF;\n" );
    str.append( "            ELSE\n" );
    str.append( "              IF a3ms_get_element_type( eiriwei.inspected_element.comparing_elements ) = etns_connected_face_set THEN\n" );
    str.append( "                IF addtn <> ddns_point_on_surface THEN\n" );
    str.append( "                  RETURN( FALSE );\n" );
    str.append( "                END_IF;\n" );
