    str.append( "            IF NOT ( a3ms_get_detected_difference_type( eiriwei.notable_instances[j].compared_elements ) IN cr.\n" );
    str.append( "                detected_difference_types ) THEN\n" );
    str.append( "              RETURN( FALSE );\n" );
    str.append( "            END_IF;\n" );
    str.append( "          ELSE\n" );
    str.append( "            IF NOT ( a3ms_get_detected_difference_type( eiriwei.notable_instances[j].comparing_elements ) IN cr.\n" );
    str.append( "                detected_difference_types ) THEN\n" );
    str.append( "              RETURN( FALSE );\n" );
    str.append( "            END_IF;\n" );
    str.append( "            IF NOT ( a3ms_get_detected_difference_type( eiriwei.notable_instances[j].compared_elements ) IN cr.\n" );
    str.append( "                detected_difference_types ) THEN\n" );
    str.append( "              RETURN( FALSE );\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_REPEAT;\n" );
