    str.append( "  ELSE\n" );
    str.append( "    IF ( schema_prefix + 'EXTENDED_TUPLE_SPACE' ) IN domain_types THEN\n" );
    str.append( "      IF space_dimension( domain ) > narg THEN\n" );
    str.append( "        RETURN( FALSE );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    ELSE\n" );
