    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  REPEAT i := 1 TO narg BY 1;\n" );
    str.append( "    arg := convert_to_operand( arguments[i] );\n" );
    str.append( "    IF NOT has_values_space( arg ) THEN\n" );
