    str.append( "    END_IF;\n" );
    str.append( "    IF NOT compatible_spaces( factor_space( domain, i ), values_space_of( arg ) ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
