    str.clear();
    str.append( "FUNCTION list_selected_components(\n" );
    str.append( "             aggr : AGGREGATE OF LIST OF maths_value;\n" );
    str.append( "             k : positive_integer\n" );
    str.append( "         ) : LIST OF maths_value;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    result : LIST OF maths_value := [];\n" );
    str.append( "    j      : INTEGER := 0;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  REPEAT i := LOINDEX( aggr ) TO HIINDEX( aggr ) BY 1;\n" );
    str.append( "    IF k <= SIZEOF( aggr[i] ) THEN\n" );
