    str.clear();
    str.append( "FUNCTION simplify_function_application(\n" );
    str.append( "             expr : function_application\n" );
    str.append( "         ) : maths_value;\n" );
    str.append( "  FUNCTION ctmv(\n" );
    str.append( "               x : GENERIC:g\n" );
    str.append( "           ) : maths_value;\n" );
    str.append( "    RETURN( convert_to_maths_value( x ) );\n" );
    str.append( "  END_FUNCTION;\n" );
    str.append( "  FUNCTION good_t(\n" );
    str.append( "               v : maths_value;\n" );
    str.append( "               tn : STRING\n" );
    str.append( "           ) : BOOLEAN;\n" );
    str.append( "    LOCAL\n" );
    str.append( "      tpl : LIST OF maths_value;\n" );
    str.append( "    END_LOCAL;\n" );
    str.append( "    IF 'LIST' IN TYPEOF( v ) THEN\n" );
    str.append( "      tpl := v;\n" );
    str.append( "      REPEAT i := 1 TO SIZEOF( tpl ) BY 1;\n" );
    str.append( "        IF NOT ( tn IN TYPEOF( tpl[i] ) ) THEN\n" );
    str.append( "          RETURN( FALSE );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_REPEAT;\n" );
    str.append( "      RETURN( TRUE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_FUNCTION;\n" );
    str.append( "  FUNCTION makec(\n" );
    str.append( "               x : REAL;\n" );
    str.append( "               y : REAL\n" );
    str.append( "           ) : complex_number_literal;\n" );
    str.append( "    RETURN( make_complex_number_literal( x, y ) );\n" );
    str.append( "  END_FUNCTION;\n" );
    str.append( "  PROCEDURE parts(\n" );
    str.append( "                c : complex_number_literal;\n" );
    str.append( "                VAR x : REAL;\n" );
    str.append( "                VAR y : REAL    );\n" );
    str.append( "    x := c.real_part;\n" );
    str.append( "    y := c.imag_part;\n" );
    str.append( "  END_PROCEDURE;\n" );
    str.append( "  CONSTANT\n" );
    str.append( "    cnlit : STRING :=\n" );
    str.append( "             schema_prefix + 'COMPLEX_NUMBER_LITERAL';\n" );
    str.append( "  END_CONSTANT;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    types         : SET OF STRING := stripped_typeof( expr.func );\n" );
    str.append( "    ef_val        : elementary_function_enumerators;\n" );
    str.append( "    is_elementary : BOOLEAN := FALSE;\n" );
    str.append( "    v             : maths_value;\n" );
    str.append( "    v1            : maths_value;\n" );
    str.append( "    v2            : maths_value;\n" );
    str.append( "    v3            : maths_value;\n" );
    str.append( "    vlist         : LIST OF maths_value := [];\n" );
    str.append( "    gexpr         : generic_expression;\n" );
    str.append( "    pairs         : SET [1 : ?] OF LIST [2 : 2] OF maths_value;\n" );
    str.append( "    boo           : BOOLEAN;\n" );
    str.append( "    lgc           : LOGICAL;\n" );
    str.append( "    cum           : LOGICAL;\n" );
    str.append( "    j             : INTEGER;\n" );
    str.append( "    k             : INTEGER;\n" );
    str.append( "    n             : INTEGER;\n" );
    str.append( "    p             : REAL;\n" );
    str.append( "    q             : REAL;\n" );
    str.append( "    r             : REAL;\n" );
    str.append( "    s             : REAL;\n" );
    str.append( "    t             : REAL;\n" );
    str.append( "    u             : REAL;\n" );
    str.append( "    str           : STRING;\n" );
    str.append( "    st2           : STRING;\n" );
    str.append( "    bin           : BINARY;\n" );
    str.append( "    bi2           : BINARY;\n" );
    str.append( "    tpl           : LIST OF maths_value;\n" );
    str.append( "    tp2           : LIST OF maths_value;\n" );
    str.append( "    mem           : SET OF maths_value := [];\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  REPEAT i := 1 TO SIZEOF( expr.arguments ) BY 1;\n" );
    str.append( "    v := simplify_maths_value( expr.arguments[i] );\n" );
    str.append( "    INSERT( vlist, v, i - 1 );\n" );
    str.append( "  END_REPEAT;\n" );
    str.append( "  IF SIZEOF( vlist ) >= 1 THEN\n" );
    str.append( "    v1 := vlist[1];\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF SIZEOF( vlist ) >= 2 THEN\n" );
    str.append( "    v2 := vlist[2];\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF SIZEOF( vlist ) >= 3 THEN\n" );
    str.append( "    v3 := vlist[3];\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'ELEMENTARY_FUNCTION_ENUMERATORS' IN types THEN\n" );
    str.append( "    ef_val := expr.func;\n" );
    str.append( "    is_elementary := TRUE;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'ELEMENTARY_FUNCTION' IN types THEN\n" );
    str.append( "    ef_val := expr.func\\elementary_function.func_id;\n" );
    str.append( "    is_elementary := TRUE;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF is_elementary THEN\n" );
    str.append( "    CASE ef_val OF\n" );
    str.append( "      ef_and            : \n" );
    str.append( "        BEGIN\n" );
    str.append( "          cum := TRUE;\n" );
    str.append( "          REPEAT i := SIZEOF( vlist ) TO 1 BY -1;\n" );
    str.append( "            IF 'LOGICAL' IN TYPEOF( vlist[i] ) THEN\n" );
    str.append( "              lgc := vlist[i];\n" );
    str.append( "              cum := cum AND lgc;\n" );
    str.append( "              IF lgc = FALSE THEN\n" );
    str.append( "                RETURN( ctmv( FALSE ) );\n" );
    str.append( "              END_IF;\n" );
    str.append( "              REMOVE( vlist, i );\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_REPEAT;\n" );
    str.append( "          IF SIZEOF( vlist ) = 0 THEN\n" );
    str.append( "            RETURN( ctmv( cum ) );\n" );
    str.append( "          END_IF;\n" );
    str.append( "          IF cum <> TRUE THEN\n" );
    str.append( "            INSERT( vlist, ctmv( cum ), 0 );\n" );
    str.append( "          END_IF;\n" );
    str.append( "          IF SIZEOF( vlist ) = 1 THEN\n" );
    str.append( "            RETURN( vlist[1] );\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END;\n" );
    str.append( "      ef_or             : \n" );
    str.append( "        BEGIN\n" );
    str.append( "          cum := FALSE;\n" );
    str.append( "          REPEAT i := SIZEOF( vlist ) TO 1 BY -1;\n" );
    str.append( "            IF 'LOGICAL' IN TYPEOF( vlist[i] ) THEN\n" );
    str.append( "              lgc := vlist[i];\n" );
    str.append( "              cum := cum OR lgc;\n" );
    str.append( "              IF lgc = TRUE THEN\n" );
    str.append( "                RETURN( ctmv( TRUE ) );\n" );
    str.append( "              END_IF;\n" );
    str.append( "              REMOVE( vlist, i );\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_REPEAT;\n" );
    str.append( "          IF SIZEOF( vlist ) = 0 THEN\n" );
    str.append( "            RETURN( ctmv( cum ) );\n" );
    str.append( "          END_IF;\n" );
    str.append( "          IF cum <> FALSE THEN\n" );
    str.append( "            INSERT( vlist, ctmv( cum ), 0 );\n" );
    str.append( "          END_IF;\n" );
    str.append( "          IF SIZEOF( vlist ) = 1 THEN\n" );
    str.append( "            RETURN( vlist[1] );\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END;\n" );
    str.append( "      ef_not            :         IF 'LOGICAL' IN TYPEOF( v1 ) THEN\n" );
    str.append( "          lgc := v1;\n" );
    str.append( "          RETURN( ctmv( NOT lgc ) );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      ef_xor            : \n" );
    str.append( "        BEGIN\n" );
    str.append( "          IF 'LOGICAL' IN TYPEOF( v1 ) THEN\n" );
    str.append( "            lgc := v1;\n" );
    str.append( "            IF 'LOGICAL' IN TYPEOF( v2 ) THEN\n" );
    str.append( "              cum := v2;\n" );
    str.append( "              RETURN( ctmv( lgc XOR cum ) );\n" );
    str.append( "            ELSE\n" );
    str.append( "              IF lgc = FALSE THEN\n" );
    str.append( "                RETURN( ctmv( v2 ) );\n" );
    str.append( "              ELSE\n" );
    str.append( "                IF lgc = UNKNOWN THEN\n" );
    str.append( "                  RETURN( ctmv( UNKNOWN ) );\n" );
    str.append( "                ELSE\n" );
    str.append( "                  RETURN( make_function_application( ef_not, [v2] ) );\n" );
    str.append( "                END_IF;\n" );
    str.append( "              END_IF;\n" );
    str.append( "            END_IF;\n" );
    str.append( "          ELSE\n" );
    str.append( "            IF 'LOGICAL' IN TYPEOF( v2 ) THEN\n" );
    str.append( "              lgc := v2;\n" );
    str.append( "              IF lgc = FALSE THEN\n" );
    str.append( "                RETURN( ctmv( v1 ) );\n" );
    str.append( "              ELSE\n" );
    str.append( "                IF lgc = UNKNOWN THEN\n" );
    str.append( "                  RETURN( ctmv( UNKNOWN ) );\n" );
    str.append( "                ELSE\n" );
    str.append( "                  RETURN( make_function_application( ef_not, [v1] ) );\n" );
    str.append( "                END_IF;\n" );
    str.append( "              END_IF;\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END;\n" );
    str.append( "      ef_negate_i       :         IF 'INTEGER' IN TYPEOF( v1 ) THEN\n" );
    str.append( "          j := v1;\n" );
    str.append( "          RETURN( ctmv( -j ) );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      ef_add_i          : \n" );
    str.append( "        BEGIN\n" );
    str.append( "          j := 0;\n" );
    str.append( "          REPEAT i := SIZEOF( vlist ) TO 1 BY -1;\n" );
    str.append( "            IF 'INTEGER' IN TYPEOF( vlist[i] ) THEN\n" );
    str.append( "              k := vlist[i];\n" );
    str.append( "              j := j + k;\n" );
    str.append( "              REMOVE( vlist, i );\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_REPEAT;\n" );
    str.append( "          IF SIZEOF( vlist ) = 0 THEN\n" );
    str.append( "            RETURN( ctmv( j ) );\n" );
