    str.append( "FUNCTION definite_integral_expr_check(\n" );
    str.append( "             operands : LIST [2 : ?] OF generic_expression;\n" );
    str.append( "             lowerinf : BOOLEAN;\n" );
    str.append( "             upperinf : BOOLEAN\n" );
    str.append( "         ) : BOOLEAN;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    nops : INTEGER := 2;\n" );
    str.append( "    vspc : maths_space;\n" );
    str.append( "    dim  : nonnegative_integer;\n" );
    str.append( "    k    : positive_integer;\n" );
    str.append( "    bspc : maths_space;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF NOT lowerinf THEN\n" );
    str.append( "    nops := nops + 1;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF NOT upperinf THEN\n" );
    str.append( "    nops := nops + 1;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF SIZEOF( operands ) <> nops THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF NOT ( 'GENERIC_VARIABLE' IN stripped_typeof( operands[2] ) ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF NOT has_values_space( operands[2] ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  vspc := values_space_of( operands[2] );\n" );
    str.append( "  IF NOT ( 'REAL_INTERVAL' IN stripped_typeof( vspc ) ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF lowerinf THEN\n" );
    str.append( "    IF min_exists( vspc ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    k := 3;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF NOT has_values_space( operands[3] ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    bspc := values_space_of( operands[3] );\n" );
    str.append( "    IF NOT compatible_spaces( bspc, vspc ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    k := 4;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF upperinf THEN\n" );
    str.append( "    IF max_exists( vspc ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF NOT has_values_space( operands[k] ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    bspc := values_space_of( operands[k] );\n" );
