    str.append( "  n := SIZEOF( lis );\n" );
    str.append( "  IF n <> ( ( u - low ) + 1 ) THEN\n" );
    str.append( "    RETURN( ? );\n" );
    str.append( "  ELSE\n" );
    str.append( "    res := [lis[1] : 0];\n" );
    str.append( "    REPEAT i := 2 TO n BY 1;\n" );
    str.append( "      res[( low + i ) - 1] := lis[i];\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    RETURN( res );\n" );
    str.append( "  END_IF;\n" );
