    str.clear();
    str.append( "FUNCTION msf_curve_check(\n" );
    str.append( "             cv : representation_item\n" );
    str.append( "         ) : BOOLEAN;\n" );
    str.append( "  IF SIZEOF( [ 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.BOUNDED_CURVE', 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.'\n" );
    str.append( "      + 'CONIC' , 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.CURVE_REPLICA', \n" );
    str.append( "      'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.LINE' , 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.OFFSET_CURVE_3D'] \n" );
    str.append( "      * TYPEOF( cv ) ) > 1 THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF ( ( 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.B_SPLINE_CURVE' IN TYPEOF( cv ) ) AND ( cv\\b_spline_curve.\n" );
    str.append( "      self_intersect = FALSE ) ) OR ( cv\\b_spline_curve.self_intersect = UNKNOWN ) THEN\n" );
    str.append( "    RETURN( TRUE );\n" );
    str.append( "  ELSE\n" );
    str.append( "    IF SIZEOF( [ 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.CONIC', 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.LINE'] \n" );
    str.append( "        * TYPEOF( cv ) ) = 1 THEN\n" );
    str.append( "      RETURN( TRUE );\n" );
    str.append( "    ELSE\n" );
    str.append( "      IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.CURVE_REPLICA' IN TYPEOF( cv ) THEN\n" );
    str.append( "        RETURN( msf_curve_check( cv\\curve_replica.parent_curve ) );\n" );
    str.append( "      ELSE\n" );
    str.append( "        IF ( 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.OFFSET_CURVE_3D' IN TYPEOF( cv ) ) AND ( ( cv\\offset_curve_3d.\n" );
    str.append( "            self_intersect = FALSE ) OR ( cv\\offset_curve_3d.self_intersect = UNKNOWN ) ) AND ( NOT ( \n" );
    str.append( "            'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.POLYLINE'  IN TYPEOF( cv\\offset_curve_3d.basis_curve ) ) ) THEN\n" );
    str.append( "          RETURN( msf_curve_check( cv\\offset_curve_3d.basis_curve ) );\n" );
    str.append( "        ELSE\n" );
    str.append( "          IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.PCURVE' IN TYPEOF( cv ) THEN\n" );
    str.append( "            RETURN( msf_curve_check( cv\\pcurve.reference_to_curve\\representation.items[1] ) AND msf_surface_check( cv\\pcurve.\n" );
    str.append( "                basis_surface ) );\n" );
    str.append( "          ELSE\n" );
    str.append( "            IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.SURFACE_CURVE' IN TYPEOF( cv ) THEN\n" );
    str.append( "              IF msf_curve_check( cv\\surface_curve.curve_3d ) THEN\n" );
    str.append( "                REPEAT i := 1 TO SIZEOF( cv\\surface_curve.associated_geometry ) BY 1;\n" );
    str.append( "                  IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.SURFACE' IN TYPEOF( cv\\surface_curve.associated_geometry[i] )\n" );
    str.append( "                      THEN\n" );
    str.append( "                    IF NOT msf_surface_check( cv\\surface_curve.associated_geometry[i] ) THEN\n" );
    str.append( "                      RETURN( FALSE );\n" );
    str.append( "                    END_IF;\n" );
    str.append( "                  ELSE\n" );
    str.append( "                    IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.PCURVE' IN TYPEOF( cv\\surface_curve.associated_geometry[i] )\n" );
    str.append( "                        THEN\n" );
    str.append( "                      IF NOT msf_curve_check( cv\\surface_curve.associated_geometry[i] ) THEN\n" );
    str.append( "                        RETURN( FALSE );\n" );
    str.append( "                      END_IF;\n" );
    str.append( "                    END_IF;\n" );
    str.append( "                  END_IF;\n" );
    str.append( "                END_REPEAT;\n" );
    str.append( "                RETURN( TRUE );\n" );
    str.append( "              END_IF;\n" );
    str.append( "            ELSE\n" );
    str.append( "              IF 'AP242_MANAGED_MODEL_BASED_3D_ENGINEERING_MIM_LF.POLYLINE' IN TYPEOF( cv ) THEN\n" );
    str.append( "                IF SIZEOF( cv\\polyline.points ) >= 3 THEN\n" );
    str.append( "                  RETURN( TRUE );\n" );
    str.append( "                END_IF;\n" );
    str.append( "              END_IF;\n" );
    str.append( "            END_IF;\n" );
    str.append( "          END_IF;\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_IF;\n" );
    str.append( "  END_IF;\n" );
    str.append( "  RETURN( FALSE );\n" );
    str.append( "END_FUNCTION;\n" );
    str.append( "\n" );
ap242_managed_model_based_3d_engineering_mim_lf::schema->AddFunction( str );
    str.clear();
    str.append( "FUNCTION subspace_of(\n" );
    str.append( "             space1, space2 : maths_space\n" );
    str.append( "         ) : LOGICAL;\n" );
    str.append( "  LOCAL\n" );
    str.append( "    spc1   : maths_space := simplify_maths_space( space1 );\n" );
    str.append( "    spc2   : maths_space := simplify_maths_space( space2 );\n" );
    str.append( "    types1 : SET OF STRING := stripped_typeof( spc1 );\n" );
    str.append( "    types2 : SET OF STRING := stripped_typeof( spc2 );\n" );
    str.append( "    lgcl   : LOGICAL;\n" );
    str.append( "    cum    : LOGICAL;\n" );
    str.append( "    es_val : elementary_space_enumerators;\n" );
    str.append( "    bnd1   : REAL;\n" );
    str.append( "    bnd2   : REAL;\n" );
    str.append( "    n      : INTEGER;\n" );
    str.append( "    sp1    : maths_space;\n" );
    str.append( "    sp2    : maths_space;\n" );
    str.append( "    prgn1  : polar_complex_number_region;\n" );
    str.append( "    prgn2  : polar_complex_number_region;\n" );
    str.append( "    aitv   : finite_real_interval;\n" );
    str.append( "  END_LOCAL;\n" );
    str.append( "  IF ( NOT EXISTS( spc1 ) ) OR ( NOT EXISTS( spc2 ) ) THEN\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF spc2 = the_generics THEN\n" );
    str.append( "    RETURN( TRUE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'ELEMENTARY_SPACE' IN types1 THEN\n" );
    str.append( "    IF NOT ( 'ELEMENTARY_SPACE' IN types2 ) THEN\n" );
    str.append( "      RETURN( FALSE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    es_val := spc2\\elementary_space.space_id;\n" );
    str.append( "    IF spc1\\elementary_space.space_id = es_val THEN\n" );
    str.append( "      RETURN( TRUE );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    CASE spc1\\elementary_space.space_id OF\n" );
    str.append( "      es_numbers        :         RETURN( FALSE );\n" );
    str.append( "      es_complex_numbers :         RETURN( es_val = es_numbers );\n" );
    str.append( "      es_reals          :         RETURN( es_val = es_numbers );\n" );
    str.append( "      es_integers       :         RETURN( es_val = es_numbers );\n" );
    str.append( "      es_logicals       :         RETURN( FALSE );\n" );
    str.append( "      es_booleans       :         RETURN( es_val = es_logicals );\n" );
    str.append( "      es_strings        :         RETURN( FALSE );\n" );
    str.append( "      es_binarys        :         RETURN( FALSE );\n" );
    str.append( "      es_maths_spaces   :         RETURN( FALSE );\n" );
    str.append( "      es_maths_functions :         RETURN( FALSE );\n" );
    str.append( "      es_generics       :         RETURN( FALSE );\n" );
    str.append( "      END_CASE;\n" );
    str.append( "    RETURN( UNKNOWN );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'FINITE_INTEGER_INTERVAL' IN types1 THEN\n" );
    str.append( "    cum := TRUE;\n" );
    str.append( "    REPEAT i := spc1\\finite_integer_interval.min TO spc1\\finite_integer_interval.max BY 1;\n" );
    str.append( "      cum := cum AND member_of( i, spc2 );\n" );
    str.append( "      IF cum = FALSE THEN\n" );
    str.append( "        RETURN( FALSE );\n" );
    str.append( "      END_IF;\n" );
    str.append( "    END_REPEAT;\n" );
    str.append( "    RETURN( cum );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'INTEGER_INTERVAL_FROM_MIN' IN types1 THEN\n" );
    str.append( "    IF 'ELEMENTARY_SPACE' IN types2 THEN\n" );
    str.append( "      es_val := spc2\\elementary_space.space_id;\n" );
    str.append( "      RETURN( ( es_val = es_numbers ) OR ( es_val = es_integers ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'INTEGER_INTERVAL_FROM_MIN' IN types2 THEN\n" );
    str.append( "      RETURN( spc1\\integer_interval_from_min.min >= spc2\\integer_interval_from_min.min );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'INTEGER_INTERVAL_TO_MAX' IN types1 THEN\n" );
    str.append( "    IF 'ELEMENTARY_SPACE' IN types2 THEN\n" );
    str.append( "      es_val := spc2\\elementary_space.space_id;\n" );
    str.append( "      RETURN( ( es_val = es_numbers ) OR ( es_val = es_integers ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF 'INTEGER_INTERVAL_TO_MAX' IN types2 THEN\n" );
    str.append( "      RETURN( spc1\\integer_interval_to_max.max <= spc2\\integer_interval_to_max.max );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    RETURN( FALSE );\n" );
    str.append( "  END_IF;\n" );
    str.append( "  IF 'FINITE_REAL_INTERVAL' IN types1 THEN\n" );
    str.append( "    IF 'ELEMENTARY_SPACE' IN types2 THEN\n" );
    str.append( "      es_val := spc2\\elementary_space.space_id;\n" );
    str.append( "      RETURN( ( es_val = es_numbers ) OR ( es_val = es_reals ) );\n" );
    str.append( "    END_IF;\n" );
    str.append( "    IF ( 'FINITE_REAL_INTERVAL' IN types2 ) OR ( 'REAL_INTERVAL_FROM_MIN' IN types2 ) OR ( 'REAL_INTERVAL_TO_MAX' IN types2 )\n" );
    str.append( "        THEN\n" );
    str.append( "      IF min_exists( spc2 ) THEN\n" );
    str.append( "        bnd1 := spc1\\finite_real_interval.min;\n" );
    str.append( "        bnd2 := real_min( spc2 );\n" );
    str.append( "        IF ( bnd1 < bnd2 ) OR ( ( bnd1 = bnd2 ) AND min_included( spc1 ) AND ( NOT min_included( spc2 ) ) ) THEN\n" );
    str.append( "          RETURN( FALSE );\n" );
    str.append( "        END_IF;\n" );
    str.append( "      END_IF;\n" );
    str.append( "      IF max_exists( spc2 ) THEN\n" );
